diagnostics.message:
Binius.BinaryBasefold.fold_advances_evaluation_poly {r : ℕ} [NeZero r] {L : Type} [Field L] [Fintype L] [DecidableEq L]
  (𝔽q : Type) [Field 𝔽q] [Fintype 𝔽q] [DecidableEq 𝔽q] [h_Fq_char_prime : Fact (Nat.Prime (ringChar 𝔽q))]
  [hF₂ : Fact (Fintype.card 𝔽q = 2)] [Algebra 𝔽q L] (β : Fin r → L) [hβ_lin_indep : Fact (LinearIndependent 𝔽q β)]
  [h_β₀_eq_1 : Fact (β 0 = 1)] {ℓ 𝓡 : ℕ} [NeZero 𝓡] {h_ℓ_add_R_rate : ℓ + 𝓡 < r} (i : Fin ℓ)
  (h_i_succ_lt : ↑i + 1 < ℓ + 𝓡) (coeffs : Fin (2 ^ (ℓ - ↑i)) → L) (r_chal : L) :
  have P_i := AdditiveNTT.intermediateEvaluationPoly 𝔽q β h_ℓ_add_R_rate ⟨↑i, ⋯⟩ coeffs;
  have f_i := fun x => Polynomial.eval (↑x) P_i;
  have f_i_plus_1 := Binius.BinaryBasefold.fold 𝔽q β ⟨↑i, ⋯⟩ h_i_succ_lt f_i r_chal;
  have new_coeffs := fun j => (1 - r_chal) * coeffs ⟨↑j * 2, ⋯⟩ + r_chal * coeffs ⟨↑j * 2 + 1, ⋯⟩;
  have P_i_plus_1 := AdditiveNTT.intermediateEvaluationPoly 𝔽q β h_ℓ_add_R_rate ⟨↑i + 1, ⋯⟩ new_coeffs;
  ∀ (y : ↥(AdditiveNTT.sDomain 𝔽q β h_ℓ_add_R_rate ⟨↑i + 1, ⋯⟩)), f_i_plus_1 y = Polynomial.eval (↑y) P_i_plus_1

